def ledger_tally() -> dict[str, int]:
    """Measured status tally of the 484 registry IDs, from the accounting ledger."""
    path = Path(".agent/verification/state/TEST_LEDGER.jsonl")
    if not path.exists():
        raise SystemExit(f"accounting ledger missing: {path}")
    tally: dict[str, int] = {}
    for line in path.read_text("utf-8").splitlines():
        if not line.strip():
            continue
        status = json.loads(line)["final_status"]
        tally[status] = tally.get(status, 0) + 1
    return tally


# Reasons that COUNT registry rows were previously written as frozen prose and
# went stale when the accounting changed (DOD-026 claimed "481 NOT_RUN_BLOCKED_
# MATERIAL and 3 PARTIAL; zero PASS", DOD-030 claimed "0 IDs have PASS", and
# DOD-031 named a gate that had since been fixed). A clause whose reason is a
# measurement must derive it from the ledger at generation time, so the text
# cannot drift from the rows it describes.
DERIVED_REASONS = {
    "DOD-026": (
        "Status taxonomy applied exactly: no unmet condition is reported as "
        "complete. MEASURED TALLY of the 484 registry IDs at this candidate -- "
        "{tally}. Each row's reason states that ID's own decision and the evidence "
        "behind it (the four NOT_RUN rows name the specific material their subject "
        "requires), and scripts/build-accounting.py --check fails if any cited "
        "evidence document has changed since the row was recorded."
    ),
    "DOD-030": (
        "All 484 registry IDs carry exactly one accounted status: 484 rows, 484 "
        "unique IDs, 0 missing, 0 duplicated, validated by scripts/build-accounting.py "
        "--check, which additionally verifies that every cited evidence document "
        "still matches its recorded digest and that the generated status summary "
        "matches the ledger. MEASURED TALLY -- {tally}."
    ),
    "DOD-031": (
        "Blockers are non-cascading and are decided per ID: the measured tally of "
        "484 registry IDs -- {tally} -- uses {distinct} distinct statuses, so no "
        "status was applied to the registry as a whole and no ID inherited a "
        "neighbour's blocker. The {blocked} NOT_RUN_BLOCKED_MATERIAL rows each name "
        "the material their subject requires, and the {na} NOT_APPLICABLE rows each "
        "carry their own applicability evidence rather than a deferral note. "
        "Independent lanes continued to completion while other lanes were red."
    ),
}


def derived_reason(clause: str, tally: dict[str, int]) -> str | None:
    template = DERIVED_REASONS.get(clause)
    if template is None:
        return None
    return template.format(
        tally=", ".join(f"{k} {tally[k]}" for k in sorted(tally)),
        distinct=len(tally),
        blocked=tally.get("NOT_RUN_BLOCKED_MATERIAL", 0),
        na=tally.get("NOT_APPLICABLE", 0),
    )


# Measurements that were written into these reasons as frozen prose and had gone
# stale by the time this was measured: DOD-008 quoted line 93.4% / function 91.39%
# / region 93.04% and per-crate figures from an earlier coverage run (the current
# measurement is 93.37 / 91.61 / 93.02); and DOD-040 said "115 tracked inputs" (the
# graph now has 141 after the test oracles were added). A claim about a measurement
# must be FORMATTED from the measurement, so these fragments are replaced with
# values read at generation time; the surrounding reasoning is left exactly as
# written. The third stale count found in the same sweep -- "473 registry
# capabilities that need material this environment does not hold" -- lives in the
# generated completion report and is rendered from the tally by
# scripts/completion-report.py instead.
DERIVED_SUBSTITUTIONS: list[tuple[str, str, str]] = [
    (
        "DOD-008",
        "**line 93.4%, function 91.39%, region 93.04%**",
        "**line {line}%, function {function}%, region {region}%**",
    ),
    ("DOD-008", "line 93.4%, function 91.39%, region 93.04%", "line {line}%, function {function}%, region {region}%"),
    ("DOD-040", "computes an epoch over 115 tracked inputs in 9 classes",
     "computes an epoch over {epoch_inputs} tracked inputs in {epoch_classes} classes"),
]


def measured_substitutions(tally: dict[str, int]) -> dict[str, object]:
    """Values for DERIVED_SUBSTITUTIONS, read from the artifacts that measure them."""
    values: dict[str, object] = {
        "blocked": tally.get("NOT_RUN_BLOCKED_MATERIAL", 0),
        "na": tally.get("NOT_APPLICABLE", 0),
    }
    coverage_path = Path(".agent/evidence/coverage/report.json")
    if coverage_path.exists():
        totals = json.loads(coverage_path.read_text("utf-8")).get("totals", {})
        values.update(
            line=totals.get("line_percent", "?"),
            function=totals.get("function_percent", "?"),
            region=totals.get("region_percent", "?"),
        )
    epoch_path = Path(".agent/verification/state/EPOCH.json")
    if epoch_path.exists():
        epoch = json.loads(epoch_path.read_text("utf-8"))
        values.update(
            epoch_inputs=epoch.get("total_inputs", "?"),
            epoch_classes=len(epoch.get("classes", {})),
        )
    return values


def apply_substitutions(clause: str, reason: str, values: dict[str, object]) -> str:
    for target, stale, template in DERIVED_SUBSTITUTIONS:
        if target == clause and stale in reason:
            reason = reason.replace(stale, template.format(**values))
    return reason


def main() -> int:
    check = "--check" in sys.argv
    with REGISTRY.open(newline="", encoding="utf-8") as fh:
        clauses = [r["dod_id"] for r in csv.DictReader(fh)]

    missing = [c for c in clauses if c not in DISPOSITIONS]
    if missing:
        raise SystemExit(f"no disposition for clauses: {missing}")
    extra = [k for k in DISPOSITIONS if k not in clauses]
    if extra:
        raise SystemExit(f"disposition for unknown clause: {extra}")

    rows = []
    tally = ledger_tally()
    substitutions = measured_substitutions(tally)
    for c in clauses:
        status, evidence, reason = DISPOSITIONS[c]
        if status == "PASS" and not Path(evidence).exists():
            raise SystemExit(f"{c}: PASS claimed but evidence {evidence} is absent")
        reason = derived_reason(c, tally) or reason
        reason = apply_substitutions(c, reason, substitutions)
        rows.append(
            {
                "dod_id": c,
                "status": status,
                "evidence_path": evidence,
                "reason": reason,
                # DOD-025 REQUIRED EVIDENCE: "Evidence index entries and content
                # hashes linked to each result." DOD-040 REQUIRED EVIDENCE:
                # "current evidence hashes". Previously neither existed, so a
                # PASS could cite a document that had since changed and nothing
                # noticed. The digest is recorded here and verified by --check.
                "evidence_sha256": evidence_digest(evidence),
                "evidence_bytes": evidence_size(evidence),
            }
        )

    if check:
        if not OUT.exists():
            print("dod-status check: FAIL (file missing)", file=sys.stderr)
            return 1
        existing = [json.loads(l) for l in OUT.read_text("utf-8").splitlines() if l.strip()]
        if len(existing) != 42:
            print(f"dod-status check: FAIL ({len(existing)} rows)", file=sys.stderr)
            return 1

        # Evidence currency. This is the teeth DOD-040 asks for: a disposition
        # whose cited evidence has changed since it was recorded is STALE, and a
        # stale PASS must be re-derived rather than trusted. Reported per clause
        # so the affected claims are named rather than counted.
        #
        # `--structure-only` skips the currency comparison. harness-validate.sh
        # uses it, because that script is ITSELF an invalidated stage: a gate
        # change reruns the harness, and stages that rewrite evidence run before
        # it, so a currency check inside it is circular in exactly the way the
        # rerun-obligation check was before it moved to verify.sh. Currency is
        # asserted in verify.sh, after the derived evidence has been refreshed.
        if "--structure-only" in sys.argv:
            print(
                f"dod-status check: ok ({len(existing)} clauses, one disposition "
                "each, structure only)"
            )
            return 0
        stale: list[str] = []
        unhashed: list[str] = []
        for row in existing:
            recorded = row.get("evidence_sha256")
            if not recorded:
                unhashed.append(row["dod_id"])
                continue
            if recorded != evidence_digest(row["evidence_path"]):
                stale.append(row["dod_id"])
        if unhashed:
            print(
                f"dod-status check: FAIL ({len(unhashed)} dispositions carry no "
                f"evidence digest, first: {unhashed[0]}) -- run "
                "scripts/build-dod-status.py to record them",
                file=sys.stderr,
            )
            return 1
        if stale:
            print(
                f"dod-status check: FAIL ({len(stale)} dispositions cite evidence "
                f"that has changed since they were recorded: {', '.join(stale)}) -- "
                "re-derive with scripts/build-dod-status.py",
                file=sys.stderr,
            )
            return 1
        print(
            f"dod-status check: ok (42 clauses, one disposition each, "
            f"all {len(existing)} evidence digests current)"
        )
        return 0

    OUT.write_text(
        "".join(json.dumps(r, sort_keys=True) + "\n" for r in rows), "utf-8"
    )
    print(f"wrote {OUT} ({len(rows)} clauses)")
    tally: dict[str, int] = {}
    for r in rows:
        tally[r["status"]] = tally.get(r["status"], 0) + 1
    for k in sorted(tally):
        print(f"  {k}: {tally[k]}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
